$results = @()
foreach ($t in $tests) {
  $sb = New-Object System.Text.StringBuilder
  [void]$sb.AppendLine('## Предусловия')
  $n = 1; foreach ($p in $t.Pre) { [void]$sb.AppendLine("$n. $p"); $n++ }
  [void]$sb.AppendLine('')
  [void]$sb.AppendLine('## Шаги')
  $n = 1; foreach ($s in $t.Steps) { $a = ($s -split '\|\|')[0].Trim(); [void]$sb.AppendLine("$n. $a"); $n++ }
  [void]$sb.AppendLine('')
  [void]$sb.AppendLine('## Ожидаемый результат')
  foreach ($s in $t.Steps) { $e = ($s -split '\|\|')[1].Trim(); [void]$sb.AppendLine("- $e") }
  [void]$sb.AppendLine('')
  [void]$sb.AppendLine('## Тестовые данные')
  [void]$sb.AppendLine("- $($t.Data)")
  $desc = $sb.ToString()

  try {
    $out = & $helper -Action create -SuiteId $suite -Title $t.Title -Desc $desc
    $obj = $out | ConvertFrom-Json
    $results += [pscustomobject]@{ title=$t.Title; status=$obj.status; test_id=$obj.test_id; url=$obj.url; raw=$out }
    Write-Output ("OK  " + $t.Title + " -> " + $obj.test_id)
  } catch {
    $results += [pscustomobject]@{ title=$t.Title; status='exception'; test_id=''; url=''; raw=$_.Exception.Message }
    Write-Output ("ERR " + $t.Title + " -> " + $_.Exception.Message)
  }
  Start-Sleep -Milliseconds 400
}

$results | ConvertTo-Json -Depth 5 | Out-File -FilePath "C:\Users\ECheredov\IdeaProjects\MyAIProject\artifacts\test-design\create_results.json" -Encoding UTF8
Write-Output "DONE"
